 1| /**
 2|  * Idempotency keys for POST and PATCH.
 3|  *
 4|  * A client may send `Idempotency-Key: <1-255 chars>`. For a given key:
 5|  * - first request: runs normally; a 2xx response is remembered (status, Location, body);
 6|  * - same method + path + body again: the remembered response is replayed with
 7|  *   `Idempotent-Replayed: true` and the handler does not run;
 8|  * - different method, path or body: 422 problem (idempotency-key-reuse);
 9|  * - while the first request is still running: 409 problem (idempotency-key-in-flight).
10|  * Non-2xx responses are not remembered, so a corrected retry may reuse the key.
11|  */
12| import { createHash } from 'node:crypto';
13| import type { RequestHandler } from 'express';
14| import { z } from 'zod';
15| import { conflict, unprocessable } from './problem.ts';
16| 
17| export const IdempotencyHeadersSchema = z.object({
18|   'idempotency-key': z.string().min(1).max(255).optional(),
19| });
20| 
21| const StoredResponseSchema = z.discriminatedUnion('state', [
22|   z.object({ state: z.literal('in-flight'), fingerprint: z.string() }),
23|   z.object({
24|     state: z.literal('done'),
25|     fingerprint: z.string(),
26|     status: z.number().int(),
27|     location: z.string().optional(),
28|     body: z.unknown(),
29|   }),
30| ]);
31| type StoredResponse = z.infer<typeof StoredResponseSchema>;
32| 
33| function fingerprint(method: string, path: string, body: unknown): string {
34|   return createHash('sha256').update(JSON.stringify([method, path, body ?? null])).digest('hex');
35| }
36| 
37| /** Middleware factory; each call owns its own key store (one per route). */
38| export function idempotency(): RequestHandler {
39|   const store = new Map<string, StoredResponse>();
40| 
41|   return (req, res, next) => {
42|     const key = IdempotencyHeadersSchema.parse(req.headers)['idempotency-key'];
43|     if (key === undefined) {
44|       next();
45|       return;
46|     }
47|     const print = fingerprint(req.method, req.originalUrl, req.body);
48|     const existing = store.get(key);
49|     if (existing !== undefined) {
50|       if (existing.fingerprint !== print) {
51|         throw unprocessable('Idempotency-Key was already used with a different request.', 'idempotency-key-reuse');
52|       }
53|       if (existing.state === 'in-flight') {
54|         throw conflict('A request with this Idempotency-Key is still being processed.', 'idempotency-key-in-flight');
55|       }
56|       res.status(existing.status).set('Idempotent-Replayed', 'true');
57|       if (existing.location !== undefined) res.location(existing.location);
58|       if (existing.body === undefined) res.end();
59|       else res.json(existing.body);
60|       return;
61|     }
62| 
63|     store.set(key, StoredResponseSchema.parse({ state: 'in-flight', fingerprint: print }));
64|     const remember = (body: unknown): void => {
65|       if (res.statusCode < 200 || res.statusCode > 299) return;
66|       const location = res.get('Location');
67|       store.set(key, StoredResponseSchema.parse({ state: 'done', fingerprint: print, status: res.statusCode, location, body }));
68|     };
69|     // Remember a JSON response before it is sent, so a retry that races the socket still replays.
70|     const json = res.json.bind(res);
71|     res.json = (body: unknown) => {
72|       remember(body);
73|       return json(body);
74|     };
75|     res.on('finish', () => {
76|       if (res.statusCode < 200 || res.statusCode > 299) store.delete(key);
77|       else if (store.get(key)?.state === 'in-flight') remember(undefined);
78|     });
79|     res.on('close', () => {
80|       if (store.get(key)?.state === 'in-flight') store.delete(key);
81|     });
